	private void warmUntilEngaged(String query) {
		// CSR entries build from KEYED probe traffic (per-subject lookups), not scans; witness predicates only
		// touched through EXISTS filters (source.has) never accumulate probe counts. Warm every predicate with
		// VALUES-seeded keyed probes first. Production analogue: witness-only predicates need demand recording
		// (tracked in plan 21's Surprises).
		String seeds = "VALUES ?a { ex:p0 ex:p1 ex:p2 ex:p3 ex:p4 ex:p5 ex:p6 ex:p7 ex:p8 }";
		for (int i = 0; i < 4; i++) {
			rows("PREFIX ex: <" + EX + "> SELECT * WHERE { " + seeds + " ?a ex:dislikes ?o }");
			rows("PREFIX ex: <" + EX + "> SELECT * WHERE { " + seeds + " ?a ex:knows ?o }");
			rows("PREFIX ex: <" + EX + "> SELECT * WHERE { " + seeds + " ?o ex:knows ?a }");
			rows("PREFIX ex: <" + EX
					+ "> SELECT * WHERE { VALUES ?a { ex:s0 ex:s1 ex:s2 ex:b0 ex:b1 } ?a ex:score ?v }");
			rows("PREFIX ex: <" + EX + "> SELECT * WHERE { VALUES ?a { ex:b0 ex:b1 } ?a ex:bigScore ?v }");
			rows("PREFIX ex: <" + EX
					+ "> SELECT * WHERE { VALUES ?a { ex:d0 ex:d1 ex:d2 } ?a ex:decimalScore ?v }");
			rows("PREFIX ex: <" + EX
					+ "> SELECT * WHERE { VALUES ?a { ex:m0 ex:m1 } ?a ex:mixedScore ?v }");
			rows("PREFIX ex: <" + EX + "> SELECT * WHERE { VALUES ?a { " + groupSubjects()
					+ " } ?a ex:bucket ?g ; ex:groupScore ?v }");
			rows("PREFIX ex: <" + EX
					+ "> SELECT * WHERE { VALUES ?a { ex:f0 ex:f1 ex:f2 } ?a ex:floatingScore ?v }");
		}
		for (int round = 0; round < 300 && KernelExecutionTestAccess.aggOpened() == 0L; round++) {
			rows(query);
		}
	}

